<?php
require_once CONFIG_DIR.'/clasificacion_documental.php';
$classificationReady=clasificacionTieneInfraestructura($conn);$academicApplications=$classificationReady?clasificacionListar($conn,(int)$evi['id_evidencia'],$user_role===3?$user_id:0):[];
?>
<section class="card" id="aplicacionesAcademicas">
  <div class="card-content">
    <div class="dashboard-section-heading"><div><h2 class="text-xl font-semibold">Aplicaciones académicas sugeridas</h2><p class="text-muted-foreground">Cada propuesta está limitada a la versión vigente de su convocatoria y requiere validación humana.</p></div><?php if($canEdit&&$classificationReady): ?><button type="button" class="btn btn-primary" id="runClassification">Evaluar reglas configuradas</button><?php endif; ?></div>
    <p id="resultadoClasificacion" role="status" class="text-muted-foreground"></p>
    <p class="dashboard-note">Una coincidencia por reglas no es clasificación semántica, cumplimiento institucional, aprobación ni dictamen oficial. Los resultados no se usan para cambiar calificaciones.</p>
    <?php if(!$classificationReady): ?><div class="dashboard-empty">El motor de clasificación aún no está instalado. No hay reglas ni criterios oficiales configurados.</div>
    <?php elseif(!$academicApplications): ?><div class="dashboard-empty">No hay propuestas guardadas. Confirma que existe una extracción y que las convocatorias vigentes tienen reglas asociadas a fuentes normativas validadas.</div>
    <?php else: foreach($academicApplications as $app): ?>
      <article class="card" style="margin-top:14px"><div class="card-content">
        <div class="dashboard-section-heading"><div><span class="dashboard-eyebrow"><?= htmlspecialchars((string)$app['instrumento'],ENT_QUOTES,'UTF-8') ?></span><h3 class="text-lg font-semibold"><?= htmlspecialchars((string)$app['instrumento_nombre'],ENT_QUOTES,'UTF-8') ?></h3><p class="text-muted-foreground">Convocatoria <?= htmlspecialchars((string)$app['convocatoria'],ENT_QUOTES,'UTF-8') ?> · versión <?= htmlspecialchars((string)($app['version_nombre']?:$app['codigo_version']),ENT_QUOTES,'UTF-8') ?></p></div><span class="badge">Documento preliminar: <?= htmlspecialchars((string)$app['validacion_documental'],ENT_QUOTES,'UTF-8') ?></span></div>
        <p class="text-sm">Coincidencia semántica: No configurada · Dictamen oficial: No emitido</p>
        <?php foreach($app['propuestas'] as $proposal): ?><section class="dashboard-status-row" style="display:block;padding:14px 0;border-top:1px solid var(--border)">
          <strong><?= htmlspecialchars((string)$proposal['criterio'],ENT_QUOTES,'UTF-8') ?><?= $proposal['subcriterio']?' · '.htmlspecialchars((string)$proposal['subcriterio'],ENT_QUOTES,'UTF-8'):'' ?></strong>
          <?php if($proposal['actividades']): ?><p>Actividad académica: <?= htmlspecialchars(implode(', ',$proposal['actividades']),ENT_QUOTES,'UTF-8') ?></p><?php endif; ?>
          <p><?= htmlspecialchars((string)$proposal['justificacion'],ENT_QUOTES,'UTF-8') ?> · Coincidencia de reglas: <?= htmlspecialchars((string)$proposal['regla'],ENT_QUOTES,'UTF-8') ?> · Confianza documental: <?= $proposal['confianza']===null?'No calculable':number_format((float)$proposal['confianza']*100,0).'%' ?> · Validación humana: <?= htmlspecialchars((string)$proposal['estado'],ENT_QUOTES,'UTF-8') ?></p>
          <?php if($proposal['requisitos_cumplidos']): ?><p>Requisitos documentados preliminarmente: <?= htmlspecialchars(implode(', ',$proposal['requisitos_cumplidos']),ENT_QUOTES,'UTF-8') ?></p><?php endif; ?>
          <?php if($proposal['requisitos_faltantes']): ?><p>Faltantes o por validar: <?= htmlspecialchars(implode(', ',$proposal['requisitos_faltantes']),ENT_QUOTES,'UTF-8') ?></p><?php endif; ?>
          <?php if(!empty($proposal['requisitos_no_aplicables'])): ?><p>Requisitos no aplicables en este periodo: <?= htmlspecialchars(implode(', ',$proposal['requisitos_no_aplicables']),ENT_QUOTES,'UTF-8') ?></p><?php endif; ?>
          <?php if($proposal['datos_utilizados']['metadatos']??[]): ?><details><summary>Información documental utilizada</summary><ul><?php foreach($proposal['datos_utilizados']['metadatos'] as $used): ?><li><?= htmlspecialchars((string)$used['campo'],ENT_QUOTES,'UTF-8') ?>: <?= htmlspecialchars(is_array($used['valor'])?implode(', ',$used['valor']):(string)($used['valor']??'sin dato'),ENT_QUOTES,'UTF-8') ?> — <?= htmlspecialchars((string)$used['resultado'],ENT_QUOTES,'UTF-8') ?></li><?php endforeach; ?></ul><p>Fuente normativa: <?= htmlspecialchars((string)($proposal['datos_utilizados']['norma']['documento']??'No indicada'),ENT_QUOTES,'UTF-8') ?><?php if(!empty($proposal['datos_utilizados']['norma']['referencia'])): ?> · <?= htmlspecialchars((string)$proposal['datos_utilizados']['norma']['referencia'],ENT_QUOTES,'UTF-8') ?><?php endif; ?></p></details><?php endif; ?>
          <?php if($canEdit&&in_array($proposal['estado'],['PROPUESTA','INFORMACION_INSUFICIENTE'],true)): ?><div style="display:flex;gap:8px;margin-top:10px"><button type="button" class="btn btn-primary classification-decision" data-proposal="<?= (int)$proposal['id_propuesta'] ?>" data-decision="CONFIRMADA">Confirmar propuesta</button><button type="button" class="btn classification-decision" data-proposal="<?= (int)$proposal['id_propuesta'] ?>" data-decision="RECHAZADA">Rechazar propuesta</button></div><?php elseif($proposal['decidido_en']): ?><p>Validada el <?= htmlspecialchars((string)$proposal['decidido_en'],ENT_QUOTES,'UTF-8') ?></p><?php endif; ?>
        </section><?php endforeach; ?>
      </div></article>
    <?php endforeach; endif; ?>
  </div>
</section>
<?php if($canEdit&&$classificationReady): ?><script>
const classificationToken=document.querySelector('meta[name="csrf-token"]')?.content||'';
document.getElementById('runClassification')?.addEventListener('click',async()=>{const body=new FormData();body.append('id_evidencia','<?= (int)$evi['id_evidencia'] ?>');try{const res=await fetch('<?= BASE_URL ?>/controllers/docente/clasificacion-ejecutar.php',{method:'POST',headers:{'X-CSRF-Token':classificationToken},body});const json=await res.json();if(!res.ok||json.status!=='ok')throw new Error(json.message||'No se pudieron evaluar las reglas.');if(json.aplicaciones?.length){location.reload();return;}document.getElementById('resultadoClasificacion').textContent=json.mensaje||json.message||'No se generaron propuestas.';}catch(error){document.getElementById('resultadoClasificacion').textContent=error.message;}});
document.querySelectorAll('.classification-decision').forEach(button=>button.addEventListener('click',async()=>{const body=new FormData();body.append('id_propuesta',button.dataset.proposal);body.append('decision',button.dataset.decision);try{const res=await fetch('<?= BASE_URL ?>/controllers/docente/clasificacion-decidir.php',{method:'POST',headers:{'X-CSRF-Token':classificationToken},body});const json=await res.json();if(!res.ok||json.status!=='ok')throw new Error(json.message||'No se pudo registrar la decisión.');alert(json.message);location.reload();}catch(error){alert(error.message);}}));
</script><?php endif; ?>
